package pi

import (
	"context"
	_ "embed"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// Compile-time interface assertions
var (
	_ agent.HookSupport   = (*PiAgent)(nil)
	_ agent.HookFreshness = (*PiAgent)(nil)
)

//go:embed entire_extension.ts
var extensionTemplate string

const (
	// extensionDirName is the directory pi auto-discovers project-local
	// extensions from.
	extensionDirName = ".pi/extensions/entire"

	// extensionFileName is the file pi loads from extensionDirName.
	extensionFileName = "index.ts"

	// entireMarker identifies the file as Entire-owned. Substring of the
	// auto-generated header so AreHooksInstalled can verify ownership by
	// content (and so it survives the ENTIRE_CMD placeholder substitution).
	entireMarker = "Auto-generated by `entire enable --agent pi`"

	// entireCmdPlaceholder is replaced at install time with the entire command,
	// which is always the `entire` binary resolved through PATH.
	entireCmdPlaceholder = "__ENTIRE_CMD__"

	// piNestedEnvVar marks a Pi process so any Pi it spawns can tell it is nested
	// and skip forwarding session lifecycle. Set and read only by the embedded
	// extension — Entire's hook subprocesses inherit it, so no Go code may treat it
	// as a skip signal.
	piNestedEnvVar = "ENTIRE_PI_NESTED"
)

func extensionPath(ctx context.Context) (string, error) {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		// Fall back to CWD for tests run outside a git repo.
		//nolint:forbidigo // explicit fallback when WorktreeRoot fails
		root, err = os.Getwd()
		if err != nil {
			return "", fmt.Errorf("resolve repo root: %w", err)
		}
	}
	return filepath.Join(root, extensionDirName, extensionFileName), nil
}

// renderExtension returns the extension file content, substituting the entire
// command the hooks shell out to. The command is always the "entire" binary; an
// extension that shells out to a path inside the working tree would run
// whatever the checked-out branch contains.
func renderExtension() string {
	return strings.ReplaceAll(extensionTemplate, entireCmdPlaceholder, "entire")
}

// InstallHooks writes the Entire pi extension to .pi/extensions/entire/index.ts.
// Returns 1 if the extension was written, 0 if already up-to-date (idempotent).
// If the file exists but content differs (e.g., an older render), it is
// rewritten as long as it is recognisable as Entire-owned (contains the
// marker). A foreign file at the same path is left untouched unless force is
// true — this protects user-authored extensions that happen to live at
// .pi/extensions/entire/index.ts.
func (a *PiAgent) InstallHooks(ctx context.Context, force bool) (int, error) {
	path, err := extensionPath(ctx)
	if err != nil {
		return 0, err
	}
	content := renderExtension()

	if !force {
		//nolint:gosec // path constructed from validated repo root
		existing, readErr := os.ReadFile(path)
		switch {
		case readErr == nil && string(existing) == content:
			return 0, nil // already up-to-date
		case readErr == nil && !strings.Contains(string(existing), entireMarker):
			return 0, fmt.Errorf("refusing to overwrite foreign file at %s; remove it or pass --force", path)
		}
	}

	//nolint:gosec // G301: pi reads the directory; standard 0755 permissions
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return 0, fmt.Errorf("create extension dir: %w", err)
	}
	//nolint:gosec // G306: pi reads the file; standard 0644 permissions
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		return 0, fmt.Errorf("write extension: %w", err)
	}
	return 1, nil
}

// UninstallHooks removes the entire pi extension directory (if present).
func (a *PiAgent) UninstallHooks(ctx context.Context) error {
	path, err := extensionPath(ctx)
	if err != nil {
		return err
	}
	dir := filepath.Dir(path)
	if err := os.RemoveAll(dir); err != nil {
		return fmt.Errorf("remove pi extension dir: %w", err)
	}
	return nil
}

// AreHooksInstalled returns true when the extension file exists and is
// recognisable as Entire-owned (contains the marker string).
//
// A missing config file is an answer, not a failure: that file is where the
// state lives, so its absence means no hooks. Anything that stops us reading the
// answer — an unreadable file, malformed config — is returned as an error, since
// "we could not tell" and "there are none" are different things to a caller
// deciding whether hooks can be left alone.
func (a *PiAgent) AreHooksInstalled(ctx context.Context) (bool, error) {
	path, err := extensionPath(ctx)
	if err != nil {
		logging.Warn(ctx, "pi: failed to resolve extension path", "err", err)
		return false, err
	}
	//nolint:gosec // path from validated repo root
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		logging.Warn(ctx, "pi: failed to read extension file", "path", path, "err", err)
		return false, fmt.Errorf("read %s: %w", path, err)
	}
	return strings.Contains(string(data), entireMarker), nil
}

// CheckHookConfig reports whether the installed extension matches what
// InstallHooks would write today. Read-only diagnostic for `entire status` and
// `entire doctor`.
//
// This matters more for pi than for agents that configure hooks in a local
// settings file: repos commonly commit .pi/extensions/entire/index.ts so every
// clone gets checkpointing without each person enabling it by hand. A committed
// extension goes stale as the template evolves, and AreHooksInstalled keeps
// returning true because the marker is still there — while the extension's own
// fireHook swallows every error by design, so broken hooks are silent. Without
// this check a stale committed extension reads as healthy forever.
func (a *PiAgent) CheckHookConfig(ctx context.Context) agent.HookConfigState {
	path, err := extensionPath(ctx)
	if err != nil {
		return agent.HooksAbsent
	}
	// Only the binary render counts as current. An extension left behind by
	// local-dev mode still carries entireMarker, so it reads as ours but
	// outdated and gets rewritten rather than being trusted as up to date.
	return agent.GeneratedHookFileState(path, entireMarker, renderExtension())
}

package agent

import (
	"fmt"
	"os"
	"path"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/worktreedir"
)

// HookConfigFile is an agent's hook-configuration file inside the worktree —
// .claude/settings.json, .cursor/hooks.json, .gemini/settings.json,
// .github/hooks/entire.json, .factory/settings.json, .codex/hooks.json,
// .opencode/plugin/entire.ts.
//
// Seven agents each carried the same four lines: filepath.Join a repo root with
// a fixed relative path, then os.ReadFile / os.MkdirAll / os.WriteFile /
// os.Remove on the result, each with a //nolint:gosec saying the path came from
// the repo root. That justification is about where the path was BUILT and says
// nothing about where it RESOLVES, which is the part that matters: `.claude` and
// its siblings live in the working tree, and a working tree arrives by clone.
// A repository carrying a checked-in symlink at `.claude` therefore had
// `entire enable` create directories and write JSON through it, to wherever it
// pointed — outside the repository included.
//
// Anchoring on worktreedir fixes that at the root rather than at each call site:
// the base is the worktree root, the agent's fixed subpath is a NAME inside it,
// and directories are created with MkdirAllNoSymlink so a symlinked component is
// refused by name instead of silently followed. It also collapses the seven
// copies into one, which is what keeps the next agent integration from
// reintroducing the pattern.
//
// Every symlink component is refused, including the file itself. os.Root blocks
// a link that escapes the worktree but follows one pointing elsewhere inside
// it; accepting the leaf would let `.claude/settings.json -> ../victim.json`
// redirect both the merge read and the subsequent write.
//
// An earlier revision of this type deliberately allowed a symlinked leaf, on the
// grounds that pointing `.claude/settings.json` at a dotfile repo is a real
// setup Entire has no business breaking. That was reconsidered, and the reason
// is worth keeping: the merge READ pulls the target's contents into what Entire
// then writes, and the write is a rename, which replaces the user's link with a
// regular file rather than following it. Both happen silently. Refusing is the
// legible version of the same outcome.
//
// The setup still works, because the thing that makes a link dangerous here is
// that it arrived with the checkout. A developer who wants one keeps it out of
// the repository — `git rm --cached .claude/settings.json` and a .gitignore
// entry — and manages it locally, which is what a dotfile workflow does anyway.
type HookConfigFile struct {
	root *os.Root
	name string
	path string
}

// OpenHookConfig returns the hook-config file at relPath inside worktreeRoot.
//
// relPath is slash-separated and relative to the worktree root
// (".cursor/hooks.json"). The directory does not need to exist: Read reports a
// missing file the way os.ReadFile does, and Write creates the parents.
func OpenHookConfig(worktreeRoot, relPath string) (*HookConfigFile, error) {
	name, err := worktreedir.Name(worktreeRoot, relPath)
	if err != nil {
		return nil, fmt.Errorf("resolve hook config path: %w", err)
	}
	root, err := worktreedir.OpenAt(worktreeRoot)
	if err != nil {
		return nil, fmt.Errorf("open worktree root: %w", err)
	}
	return &HookConfigFile{
		root: root,
		name: name,
		path: filepath.Join(worktreeRoot, filepath.FromSlash(name)),
	}, nil
}

// Path is the file's absolute path, for messages and for the agent config that
// has to name it. It is not an invitation to do I/O on the result.
func (f *HookConfigFile) Path() string { return f.path }

// Read returns the file's contents. A missing file is reported unwrapped so
// callers can classify it with os.IsNotExist, which is how every agent's
// install path decides between "merge into existing" and "write fresh".
func (f *HookConfigFile) Read() ([]byte, error) {
	return osroot.ReadFileNoFollow(f.root, f.name) //nolint:wrapcheck // see doc comment
}

// Exists reports whether the file is present at a path Entire will read.
//
// A symlinked parent directory counts as absent rather than as an error, since
// the signature has nowhere to put one. That is the useful answer: every caller
// uses this to choose between merging into an existing file and writing a fresh
// one, and Write refuses the same path with a message that names the link.
func (f *HookConfigFile) Exists() bool {
	info, err := osroot.LstatNoSymlinks(f.root, f.name)
	return err == nil && info.Mode()&os.ModeSymlink == 0
}

// Write writes data, creating parent directories. A parent that already exists
// as a symlink is refused with osroot.ErrSymlinkedPath rather than followed.
func (f *HookConfigFile) Write(data []byte, perm os.FileMode) error {
	if dir := path.Dir(f.name); dir != "." {
		if err := osroot.MkdirAllNoSymlink(f.root, dir, 0o750); err != nil {
			return fmt.Errorf("create %s: %w", path.Dir(f.path), err)
		}
	}
	if info, err := osroot.LstatNoSymlinks(f.root, f.name); err == nil && info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("write %s: %w", f.path, osroot.ErrSymlinkedPath)
	} else if err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("write %s: %w", f.path, err)
	}
	if err := jsonutil.WriteFileAtomicIn(f.root, f.name, data, perm); err != nil {
		return fmt.Errorf("write %s: %w", f.path, err)
	}
	return nil
}

// Remove deletes the file. A file that is not there is not an error; a
// symlinked parent directory is, because the file this would delete is at the
// far end of a link Entire did not create.
func (f *HookConfigFile) Remove() error {
	if err := osroot.RemoveNoSymlinks(f.root, f.name); err != nil {
		return fmt.Errorf("remove %s: %w", f.path, err)
	}
	return nil
}

// Root exposes the underlying root and the file's name inside it, for the
// callers that need a descriptor rather than the bytes. Both are Codex, which
// bounds .codex/hooks.json on its stat size before reading any of it: Read is
// an unbounded io.ReadAll, so it cannot express a limit, and the file arrives
// with the checkout. Everything else must use Read/Write/Remove.
//
// The root is owned by the shared registry, so do not close it. Callers must go
// through the osroot no-follow primitives rather than resolving name with
// Root.Open, which is what Read does for them.
func (f *HookConfigFile) Root() (*os.Root, string) { return f.root, f.name }

// GeneratedState is GeneratedHookFileState for a file read through this root.
// See that function for what marker and render mean.
func (f *HookConfigFile) GeneratedState(marker, render string) HookConfigState {
	data, err := f.Read()
	if err != nil {
		return HooksAbsent
	}
	return generatedStateFromContent(string(data), marker, render)
}

package opencode

import (
	"context"
	"errors"
	"fmt"
	"os"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// Compile-time interface assertions
var (
	_ agent.HookSupport   = (*OpenCodeAgent)(nil)
	_ agent.HookFreshness = (*OpenCodeAgent)(nil)
)

const (
	// pluginFileName is the name of the plugin file written to .opencode/plugins/
	pluginFileName = "entire.ts"

	// pluginDirName is the directory under .opencode/ where plugins live
	pluginDirName = "plugins"

	// entireMarker is a string present in the plugin file to identify it as Entire's
	entireMarker = "Auto-generated by `entire enable --agent opencode`"
)

// pluginConfig returns .opencode/plugins/entire.ts for the current worktree,
// opened through the worktree's root so the plugin directory is created and
// written as a name inside the repository rather than through whatever a
// checked-in `.opencode` symlink points at.
func pluginConfig(ctx context.Context) (*agent.HookConfigFile, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		// Fallback to CWD if not in a git repo (e.g., during tests)
		//nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests run outside git repos)
		repoRoot, err = os.Getwd()
		if err != nil {
			return nil, fmt.Errorf("failed to get current directory: %w", err)
		}
	}
	return agent.OpenHookConfig(repoRoot, ".opencode/"+pluginDirName+"/"+pluginFileName) //nolint:wrapcheck // agent.HookConfigFile already names the file in its error
}

// renderPlugin returns the plugin file content. The template names the "entire"
// binary directly — there is nothing to substitute, and deliberately so: a plugin
// that shelled out to a path inside the working tree would run whatever the
// checked-out branch contains.
func renderPlugin() string {
	return pluginTemplate
}

// InstallHooks writes the Entire plugin file to .opencode/plugins/entire.ts.
// Returns 1 if the plugin was written, 0 if already up-to-date (idempotent).
// If the file exists but content differs (e.g., an older render), it is rewritten.
func (a *OpenCodeAgent) InstallHooks(ctx context.Context, force bool) (int, error) {
	cfg, err := pluginConfig(ctx)
	if err != nil {
		return 0, err
	}

	content := renderPlugin()

	// Check if already installed with identical content (idempotent) unless force
	if !force {
		if existing, readErr := cfg.Read(); readErr == nil {
			if string(existing) == content {
				return 0, nil // Already up-to-date
			}
		}
	}

	// Write creates .opencode/plugins with MkdirAllNoSymlink. 0644 because
	// OpenCode reads the plugin itself.
	if err := cfg.Write([]byte(content), 0o644); err != nil {
		return 0, err //nolint:wrapcheck // agent.HookConfigFile already names the file in its error
	}

	return 1, nil
}

// UninstallHooks removes the Entire plugin file.
func (a *OpenCodeAgent) UninstallHooks(ctx context.Context) error {
	cfg, err := pluginConfig(ctx)
	if err != nil {
		return err
	}
	return cfg.Remove() //nolint:wrapcheck // agent.HookConfigFile already names the file in its error
}

// AreHooksInstalled checks if the Entire plugin file exists and contains the marker.
//
// A missing config file is an answer, not a failure: that file is where the
// state lives, so its absence means no hooks. Anything that stops us reading the
// answer — an unreadable file, malformed config — is returned as an error, since
// "we could not tell" and "there are none" are different things to a caller
// deciding whether hooks can be left alone.
func (a *OpenCodeAgent) AreHooksInstalled(ctx context.Context) (bool, error) {
	cfg, err := pluginConfig(ctx)
	if err != nil {
		logging.Warn(ctx, "opencode: failed to resolve plugin path", "err", err)
		return false, err
	}

	data, err := cfg.Read()
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		logging.Warn(ctx, "opencode: failed to read plugin file", "path", cfg.Path(), "err", err)
		return false, fmt.Errorf("read %s: %w", cfg.Path(), err)
	}

	return strings.Contains(string(data), entireMarker), nil
}

// CheckHookConfig reports whether the installed plugin matches what
// InstallHooks would write today. Read-only diagnostic for `entire status` and
// `entire doctor`; same committed-and-stale exposure as Pi's extension, since
// .opencode/plugins/entire.ts is likewise a generated file repos commit so
// every clone is covered.
func (a *OpenCodeAgent) CheckHookConfig(ctx context.Context) agent.HookConfigState {
	cfg, err := pluginConfig(ctx)
	if err != nil {
		return agent.HooksAbsent
	}
	// Only the binary render counts as current. A plugin left behind by
	// local-dev mode still carries entireMarker, so it reads as ours but
	// outdated and gets rewritten rather than being trusted as up to date.
	return cfg.GeneratedState(entireMarker, renderPlugin())
}

// GetSupportedHooks returns the normalized lifecycle events this agent supports.
// OpenCode's native hooks map to standard agent lifecycle events:
//   - session-start → HookSessionStart
//   - session-end   → HookSessionEnd
//   - turn-start    → HookUserPromptSubmit (user prompt triggers a turn)
//   - turn-end      → HookStop (agent response complete)
//
// Note: HookNames() returns 5 hooks (including "compaction"), but GetSupportedHooks()
// returns only 4. The "compaction" hook is OpenCode-specific with no standard HookType
// mapping — it is handled via ParseHookEvent but not advertised as a standard lifecycle event.
func (a *OpenCodeAgent) GetSupportedHooks() []agent.HookType {
	return []agent.HookType{
		agent.HookSessionStart,
		agent.HookSessionEnd,
		agent.HookUserPromptSubmit,
		agent.HookStop,
	}
}

