package agent

import (
	"context"
	"fmt"
	"io"
	"os"
	"os/exec"
	"runtime"
	"slices"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
)

// GeneratedHookFileState reports hook-config drift for agents whose entire
// Entire integration is one generated file in the repo (Pi's extension,
// OpenCode's plugin), for use by HookFreshness implementations.
//
// The file counts as ours only if it contains marker, and as current only if it
// matches render — what InstallHooks writes today. Pass exactly that one render:
// anything else still carrying the marker (a template edit, or a file left by an
// older version) must read as outdated so the next install replaces it. Passing a
// legacy render here would mark it current and strand it on disk forever, which
// is what TestCheckHookConfig_LegacyLocalDevIsDrift pins against. Matching on
// content rather than a stamped version keeps this honest for free — any edit to
// the embedded template makes installed copies read as outdated without anyone
// remembering to bump anything.
//
// Line endings are normalized before comparing. These files are generated with
// LF but are typically committed, so on Windows a checkout under the default
// core.autocrlf=true hands us CRLF and byte equality never holds. That would
// report permanent drift the user cannot clear: InstallHooks writes LF back,
// and the next checkout converts it to CRLF again.
//
// A file that exists but lacks marker reads as HooksAbsent, not HooksOutdated:
// InstallHooks refuses to overwrite a foreign file at our path, so there is no
// Entire config there for us to call stale.
func GeneratedHookFileState(path, marker, render string) HookConfigState {
	data, err := os.ReadFile(path) //nolint:gosec // path constructed from validated repo root
	if err != nil {
		return HooksAbsent
	}
	return generatedStateFromContent(string(data), marker, render)
}

// generatedStateFromContent is GeneratedHookFileState once the bytes are in
// hand, shared with HookConfigFile.GeneratedState, which reads them through a
// root instead of through a path.
func generatedStateFromContent(content, marker, render string) HookConfigState {
	if !strings.Contains(content, marker) {
		return HooksAbsent
	}
	if normalizeLineEndings(content) == normalizeLineEndings(render) {
		return HooksCurrent
	}
	return HooksOutdated
}

// normalizeLineEndings rewrites CRLF to LF so content comparison survives a
// Windows checkout. Lone CR is left alone: no generator here emits it, and
// touching it would rewrite content that is genuinely different.
func normalizeLineEndings(s string) string {
	if !strings.Contains(s, "\r\n") {
		return s
	}
	return strings.ReplaceAll(s, "\r\n", "\n")
}

=== worktreedir ===
// Package worktreedir owns access to the files of the working tree itself.
//
// It is the third of Entire's three anchors, alongside entiredir (.entire) and
// gitdir (the git common dir), and the loosest of them: a root here contains
// operations to the repository rather than to a directory Entire owns. That is
// still worth having, because the paths that reach these reads and writes are
// not Entire's own:
//
//   - Checkpoint writes read working files named by `git status` output, on the
//     hook path, to turn them into blobs.
//   - Rewind writes working files named by git TREE ENTRIES out of a checkpoint,
//     which may have been fetched from a remote. Its restore half already opened
//     a root for exactly this reason; the reads beside it did not.
//   - Diff-stat and gather read working files named from status output too.
//
// A root makes "cannot leave the repository" a property of the handle rather
// than of each caller remembering to validate. It is not a substitute for the
// tree-path validation those callers do — normalizeRepoRelativeTreePath still
// rejects names that are not repo-relative before they are used as git paths —
// it is the layer underneath it.
package worktreedir

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// Open returns the shared *os.Root over the current worktree root. The returned
// root is owned by the registry and shared with every other caller; do not close
// it.
func Open(ctx context.Context) (*os.Root, error) {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve worktree root: %w", err)
	}
	return OpenAt(root)
}

// OpenAt is Open for an explicit worktree root, for callers that resolved one
// already or that act on a worktree other than the current directory.
func OpenAt(worktreeRoot string) (*os.Root, error) {
	if worktreeRoot == "" {
		return nil, errors.New("worktreedir: worktree root is required")
	}
