func checkAgentDirSymlinks(cmd *cobra.Command) {
	ctx := cmd.Context()
	w := cmd.OutOrStdout()

	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return // no repository: nothing to check
	}
	root, err := worktreedir.OpenAt(worktreeRoot)
	if err != nil {
		return
	}

	var found []string
	reported := make(map[string]struct{})
	for _, candidate := range agentSymlinkCheckPaths() {
		name, ok := firstSymlinkedComponent(root, candidate)
		if !ok {
			continue
		}
		// Several candidates share a prefix (.claude, .claude/skills), so a
		// symlinked .claude would otherwise be named once per candidate.
		if _, dup := reported[name]; dup {
			continue
		}
		reported[name] = struct{}{}
		found = append(found, name)
	}
	if len(found) == 0 {
		return
	}

	fmt.Fprintln(w, "Agent config directories: SYMLINKS PRESENT")
	for i, name := range found {
		if i == symlinkReportLimit {
			fmt.Fprintf(w, "  ... and %d more\\n", len(found)-symlinkReportLimit)
			break
		}
		fmt.Fprintf(w, "  %s -> %s\\n", name, readlinkOrUnknownIn(root, name))
	}
	fmt.Fprintln(w, "  Entire will not create or write through a symlinked directory here, so the")
	fmt.Fprintln(w, "  hooks and skills that belong under these paths are not installed, and")
	fmt.Fprintln(w, "  `entire status` reports them as absent rather than as blocked.")
	fmt.Fprintln(w, "  Fix: replace each path above with a real directory. If it is tracked in git,")
	fmt.Fprintln(w, "  `git rm --cached` it first, and add it to .gitignore so it does not come back.")
}

// agentSymlinkCheckPaths returns the worktree-relative paths whose directory
// components Entire creates or writes through on behalf of an agent, sorted and
// deduplicated.
//
// Derived from the registry and from the scaffold templates rather than from a
// list kept here, so a newly integrated agent is covered without anyone
// remembering this function. The scaffolds are included separately because two
// of them land outside the owning agent's ProtectedDirs (Codex's search skill in
// .agents, Copilot's in .github), and their parents are Entire's to create.
func agentSymlinkCheckPaths() []string {
	seen := make(map[string]struct{})
	var out []string
	add := func(p string) {
		p = filepath.ToSlash(p)
		if p == "" || p == "." || p == "/" {
			return
		}
		if _, ok := seen[p]; ok {
			return
		}
		seen[p] = struct{}{}
		out = append(out, p)
	}

	for _, dir := range agent.AllProtectedDirs() {
		add(dir)
	}
	for _, name := range agent.List() {
		if relPath, _, ok := searchSkillTemplate(name); ok {
			add(path.Dir(filepath.ToSlash(relPath)))
		}
		if relPath, _, ok := agentHelpSkillTemplate(name); ok {
			add(path.Dir(filepath.ToSlash(relPath)))
		}
	}

	slices.Sort(out)
	return out
}

// firstSymlinkedComponent returns the shortest prefix of name that is a symlink.
//
// Prefixes are examined shortest first so the walk stops at a link before it
// would resolve anything through it, which is both the correct answer to report
// (the outermost link is the one to replace) and the reason a plain root.Lstat
// of the full name is not enough: that call follows an in-root parent link and
// reports the far end's mode.
//
// A component that does not exist ends the walk with nothing to report: an
// absent .claude is not a misconfiguration.
func firstSymlinkedComponent(root *os.Root, name string) (string, bool) {
	components := strings.Split(name, "/")
	for i := range components {
		prefix := strings.Join(components[:i+1], "/")
		info, err := root.Lstat(prefix)
		if err != nil {
			return "", false
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return prefix, true
		}
	}
	return "", false
}

